<?php
namespace App\Controllers\Admin;use App\Core\Controller;use App\Helpers\AdminAuth;
class Auth extends Controller {public function login():void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);AdminAuth::ensure($this->db());$b=$this->getBody();$email=strtolower(trim((string)($b['email']??'')));$password=(string)($b['password']??'');$u=$this->db()->query('SELECT * FROM vp_admin_users WHERE email=? AND is_active=1 LIMIT 1',[$email])->row_array();if(!$u||!password_verify($password,$u['password_hash']))$this->error('Invalid credentials',401);AdminAuth::login($u);$this->success(AdminAuth::user(),'Login berhasil');}public function me():void{$this->handleCors();$u=AdminAuth::user();if(!$u)$this->error('Unauthorized',401);$this->success($u,'Authenticated');}public function logout():void{$this->handleCors();AdminAuth::logout();$this->success(null,'Logout berhasil');}public function changePassword():void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$a=AdminAuth::user();if(!$a)$this->error('Unauthorized',401);$b=$this->getBody();$current=(string)($b['current_password']??'');$new=(string)($b['new_password']??'');$confirm=(string)($b['confirm_password']??'');if(strlen($new)<8)$this->error('Password baru minimal 8 karakter',422);if($confirm!==''&&$confirm!==$new)$this->error('Konfirmasi password tidak cocok',422);$u=$this->db()->query('SELECT * FROM vp_admin_users WHERE id=? LIMIT 1',[(int)$a['id']])->row_array();if(!$u||!password_verify($current,$u['password_hash']))$this->error('Password saat ini salah',422);if($new===$current)$this->error('Password baru harus berbeda dari password saat ini',422);$now=$GLOBALS['now']??date('Y-m-d H:i:s');$this->db()->update('vp_admin_users',['password_hash'=>password_hash($new,PASSWORD_DEFAULT),'updated_at'=>$now],['id'=>(int)$u['id']]);$this->success(null,'Password berhasil diubah');}}
